import json, urllib.request, urllib.parse

headers = {"User-Agent": "Mozilla/5.0"}

def fetch(sym):
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(sym)}?interval=1d&range=5d"
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.load(r)

for sym in ["CL=F","GC=F","SI=F","GC=F","XAUUSD=X","SI=F"]:
    try:
        d = fetch(sym)
        m = d["chart"]["result"][0]["meta"]
        q = d["chart"]["result"][0]["indicators"]["quote"][0]
        print(f"--- {sym} ---")
        for k in ["symbol","shortName","regularMarketPrice","regularMarketChangePercent","fulldayPrice","fulldayChange","fulldayChangePercent","chartPreviousClose","regularMarketDayHigh","regularMarketDayLow","regularMarketTime"]:
            print(f"  {k}: {m.get(k)}")
        print("  opens:", q["open"])
        print("  closes:", q["close"])
    except Exception as e:
        print(f"{sym} FAIL:", e)

# try quote API v7
for sym in ["CL=F","GC=F","SI=F"]:
    url = f"https://query1.finance.yahoo.com/v7/finance/quote?symbols={urllib.parse.quote(sym)}"
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            d = json.load(r)
        q = d["quoteResponse"]["result"][0]
        print(f"v7 {sym}: price={q.get('regularMarketPrice')} chg%={q.get('regularMarketChangePercent')} prev={q.get('regularMarketPreviousClose')} open={q.get('regularMarketOpen')}")
    except Exception as e:
        print(f"v7 {sym} FAIL:", e)
